sql.sql:
SELECT MAX(date_day) as last_date
FROM dim_date
WHERE date_key = (SELECT MAX(date_key) FROM dim_date);

SELECT MAX(date_day) as last_date
FROM dim_date
WHERE date_key = (SELECT MAX(date_key) FROM dim_date WHERE date_key <= (SELECT MAX(date_key) FROM dim_date));

SELECT MAX(date_day) as last_date
FROM dim_date
WHERE calendar_year = 2011;

SELECT MAX(date_day) as last_date
FROM dim_date
WHERE calendar_year = 2011 AND calendar_quarter = 4;

SELECT MAX(date_day) as last_date
FROM dim_date
WHERE calendar_year = 2011 AND month_of_year = 12;

SELECT MAX(date_day) as last_date
FROM dim_date
WHERE calendar_year = 2011 AND month_of_year = 12 AND date_day <= '2011-12-09';

